using System.Text.Json;
namespace LeoLauncher;
static class PlannerFeatureTests
{
    static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in All(c))yield return nested;}}
    public static Dictionary<string,bool> Check(string dir){var checks=new Dictionary<string,bool>();var day=DateOnly.FromDateTime(DateTime.Today);var now=DateTimeOffset.Now;string file=Path.Combine(dir,"repeat-fixture.json");if(File.Exists(file))File.Delete(file);
        var daily=new TodoStore(file);var first=daily.AddRepeating("每天运动",day,"daily",new DateTimeOffset(day.ToDateTime(new TimeOnly(19,30))));checks["daily_occurrences_generated_with_same_local_reminder_time"]=daily.Items.Count==36&&daily.Items.All(t=>t.Reminder?.LocalDateTime.TimeOfDay==new TimeSpan(19,30,0));var reopened=new TodoStore(file);reopened.EnsureThrough(day.AddDays(42));int count=reopened.Items.Count;reopened.EnsureThrough(day.AddDays(42));checks["recurrence_extends_once_and_survives_restart"]=count==43&&new TodoStore(file).Items.Count==43;
        var removed=reopened.Delete(first.Id)!;reopened.EnsureThrough(day.AddDays(45));checks["deleting_one_occurrence_does_not_regenerate_it"]=reopened.Items.All(t=>t.Id!=first.Id)&&reopened.Items.Any(t=>t.Day==day.AddDays(1));reopened.Restore(removed);checks["deleted_occurrence_can_be_restored"]=reopened.Items.Any(t=>t.Id==first.Id);reopened.SetReminder(first.Id,new DateTimeOffset(day.ToDateTime(new TimeOnly(21,15))),true);reopened.EnsureThrough(day.AddDays(48));checks["series_reminder_changes_apply_to_existing_and_new_instances"]=reopened.Items.All(t=>t.Reminder?.LocalDateTime.TimeOfDay==new TimeSpan(21,15,0));
        reopened.Toggle(first.Id);reopened.StopRepeating(first.SeriesId!,day);reopened.EnsureThrough(day.AddDays(60));checks["stop_repeating_preserves_history_and_stops_future_generation"]=reopened.Items.Count==1&&reopened.Items[0].Completed!=null&&reopened.RuleFor(first.SeriesId)?.Active==false;
        var weekly=new TodoStore(null);weekly.AddRepeating("每周踢球",day,"weekly");weekly.EnsureThrough(day.AddDays(56));checks["weekly_occurrences_keep_weekday_across_months"]=weekly.Items.Count==9&&weekly.Items.All(t=>t.Day.DayOfWeek==day.DayOfWeek);
        var defer=new TodoStore(null);var old=defer.Add("旧事项",day.AddDays(-3),now.AddDays(-3));defer.MarkNotified([old.Id],now);var completed=defer.Add("已完成",day);defer.Toggle(completed.Id);int changed=defer.Postpone([old.Id,completed.Id]);var moved=defer.Items.Single(t=>t.Id==old.Id);checks["postpone_skips_completed_and_moves_overdue_to_tomorrow"]=changed==1&&moved.Day==day.AddDays(1)&&defer.Items.Single(t=>t.Id==completed.Id).Day==day;checks["postpone_shifts_reminder_and_resets_delivery"]=moved.Reminder?.LocalDateTime==now.AddDays(1).LocalDateTime&&moved.Notified==null;
        var repeating=new TodoStore(null);var occurrence=repeating.AddRepeating("每日习惯",day,"daily");repeating.Postpone([occurrence.Id]);repeating.EnsureThrough(day.AddDays(36));checks["postponed_repeat_merges_without_duplicate_or_regeneration"]=repeating.Items.All(t=>t.Id!=occurrence.Id)&&repeating.Items.Count(t=>t.Day==day.AddDays(1))==1;
        var match=new FootballMatch("fixture-match",now.AddHours(4),"西甲","83","Barcelona","86","Real Madrid","pre","STATUS_SCHEDULED","VS",true);var plans=new TodoStore(null);var added=plans.AddMatch(match,now);var again=plans.AddMatch(match,now);checks["match_import_is_deduplicated_with_ten_minute_reminder"]=added.Added&&!again.Added&&plans.Items.Count==1&&added.Task.Reminder==match.Kickoff.AddMinutes(-10)&&added.Task.Day==DateOnly.FromDateTime(match.Kickoff.LocalDateTime);bool rejected=false;try{plans.AddMatch(match with{Id="past",Kickoff=now.AddHours(-1)},now);}catch(ArgumentException){rejected=true;}checks["past_or_unscheduled_matches_cannot_be_added"]=rejected;try{plans.AddMatch(match with{Id="unknown",TimeKnown=false},now);checks["past_or_unscheduled_matches_cannot_be_added"]=false;}catch(ArgumentException){}
        using(var window=new FootballForm(true,plans)){window.PreviewData([match with{Id="fixture-click"}]);window.Show();Application.DoEvents();window.PreviewData([match with{Id="fixture-click"}]);var button=All(window).OfType<BarcaButton>().Single(x=>x.AccessibleName=="加入清单并提醒");button.PerformClick();Application.DoEvents();checks["football_button_writes_to_shared_planner_store"]=plans.Items.Count==2&&button.Text=="已加入清单"&&!button.Enabled;}
        using(var footer=new FootTools(130,true)){footer.Show();Application.DoEvents();checks["footer_three_buttons_and_disclosure_toggle"]=footer.VerifyDisclosure();footer.ApplyScale(230);checks["expanded_footer_scales_and_fits_reserved_space"]=footer.VerifyDisclosure()&&footer.ReservedSpace>=footer.Height+footer.Gap;checks["search_and_utility_disclosure_do_not_overlap"]=footer.VerifySearchToggle();}
        checks["repeat_instructions_route_to_brain"]=QuickRouter.Route("添加待办，每天运动").Kind==QuickKind.Ai;File.Delete(file);return checks;
    }
}
